CREATE TYPE "PricingTier" AS ENUM ('STANDARD','PREMIUM','CUSTOM');
CREATE TABLE "PricingRule" ("id" TEXT NOT NULL,"key" VARCHAR(80) NOT NULL,"tier" "PricingTier" NOT NULL,"amount" INTEGER,"currency" VARCHAR(3) NOT NULL DEFAULT 'TZS',"isActive" BOOLEAN NOT NULL DEFAULT true,"effectiveFrom" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"effectiveTo" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PricingRule_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PricingRule_key_key" ON "PricingRule"("key"); CREATE INDEX "PricingRule_tier_isActive_effectiveFrom_idx" ON "PricingRule"("tier","isActive","effectiveFrom");
CREATE TABLE "OrderItem" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"kind" VARCHAR(60) NOT NULL,"description" VARCHAR(240) NOT NULL,"quantity" INTEGER NOT NULL,"unitAmount" INTEGER NOT NULL,"totalAmount" INTEGER NOT NULL,"currency" VARCHAR(3) NOT NULL DEFAULT 'TZS',"sourceTemplateId" TEXT,"sourceDesignId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OrderItem_pkey" PRIMARY KEY ("id")); CREATE INDEX "OrderItem_orderId_idx" ON "OrderItem"("orderId"); ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"actorUserId" TEXT,"action" VARCHAR(80) NOT NULL,"entityType" VARCHAR(80) NOT NULL,"entityId" VARCHAR(120),"beforeData" JSONB,"afterData" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id")); CREATE INDEX "AuditLog_actorUserId_createdAt_idx" ON "AuditLog"("actorUserId","createdAt"); CREATE INDEX "AuditLog_entityType_entityId_createdAt_idx" ON "AuditLog"("entityType","entityId","createdAt"); ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_actorUserId_fkey" FOREIGN KEY ("actorUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
